// Local configuration is generated by the installer and never packaged.
"use strict";
const fs = require("node:fs"),
  path = require("node:path");
const file =
  process.env.CODEX_SESSION_BRIDGE_CONFIG ||
  path.join(__dirname, "../.bridge-state/runtime.json");
module.exports = JSON.parse(fs.readFileSync(file, "utf8"));
